import SwiftUI

struct ReceiptForm:View {
    @EnvironmentObject var api:API;let stock:Row
    @State private var lot="";@State private var reference="";@State private var location="";@State private var owner="owned";@State private var packaging="wrapped";@State private var opened=false;@State private var packs="";@State private var per="";@State private var loose="0";@State private var key=UUID().uuidString;@State private var saved=false
    var body:some View {Form {Text(stock.text("name"));TextField("New pallet / lot ID",text:$lot);TextField("Delivery reference and line",text:$reference);TextField("Location",text:$location);Picker("Ownership",selection:$owner) {Text("Sunnyland owned").tag("owned");Text("Consignment").tag("consignment")};Picker("Packaging",selection:$packaging) {Text("Wrapped").tag("wrapped");Text("Flagged pallet").tag("flagged");Text("Loose").tag("loose")};Toggle("Opened",isOn:$opened);TextField("Full packs or flag intervals",text:$packs).keyboardType(.numberPad);TextField("Confirmed sheets per pack / interval",text:$per).keyboardType(.numberPad);TextField("Additional loose sheets",text:$loose).keyboardType(.numberPad);Text("Only receive a new delivery here. Use Recount for stock already recorded.").font(.footnote);Button(saved ? "Receipt saved":"Receive stock") {api.run {_ = try await api.action("receipt",["id":lot,"stock":stock.id,"reference":reference,"location":location,"owner":owner,"packaging":packaging,"opened":opened,"packs":Int(packs) ?? -1,"per":Int(per) ?? -1,"loose":Int(loose) ?? -1],key:key);saved=true}}.disabled(saved||api.working)}.navigationTitle("Receive delivery")}
}
struct CutForm:View {
    @EnvironmentObject var api:API;let stock:Row
    @State private var rule="";@State private var lot="";@State private var parents="";@State private var output="";@State private var target="";@State private var location="";@State private var reason="";@State private var key=UUID().uuidString;@State private var saved=false
    var body:some View {Form {Text(stock.text("name"));Picker("Approved cut",selection:$rule) {Text("Choose cut").tag("");ForEach(api.cutrules.filter {$0.text("source")==stock.id && $0.flag("enabled")}) {r in Text(r.text("target")+" · \(r.number("yield")) per parent").tag(r.id)}};Picker("Parent pallet / lot",selection:$lot) {Text("Choose lot").tag("");ForEach(api.lots.filter {$0.text("stock")==stock.id && $0.text("owner") != "unknown"}) {l in Text(l.id+" · "+l.text("owner")+" · \(l.number("sheets")) sheets").tag(l.id)}};TextField("Parent sheets used",text:$parents).keyboardType(.numberPad);TextField("Usable cut sheets produced",text:$output).keyboardType(.numberPad);TextField("New child lot ID",text:$target);TextField("Child lot location",text:$location);TextField("Cut / waste details",text:$reason,axis:.vertical);Text("Ownership follows the parent lot. Parent sheets are removed once and usable child sheets are added once.").font(.footnote);Button(saved ? "Cut saved":"Confirm completed cut") {api.run {_ = try await api.action("cut",["rule":rule,"sourceLot":lot,"sourceSheets":Int(parents) ?? 0,"outputSheets":Int(output) ?? -1,"targetLot":target,"location":location,"reason":reason],key:key);saved=true}}.disabled(saved||api.working)}.navigationTitle("Cut stock")}
}
struct JobSetupForm:View {
    @EnvironmentObject var api:API
    @State private var number="";@State private var name="";@State private var sectionID="";@State private var sectionName="";@State private var rep="";@State private var query="";@State private var selected:Set<String>=[];@State private var confirmed=false;@State private var key=UUID().uuidString;@State private var saved=false
    var body:some View {Form {Section("Verify against printIQ") {TextField("Job number, e.g. J064383",text:$number).textInputAutocapitalization(.characters);TextField("Job description",text:$name);TextField("Exact section ID",text:$sectionID);TextField("Section name",text:$sectionName);Picker("Rep",selection:$rep) {Text("Choose rep").tag("");ForEach(api.users.filter { ["rep","manager"].contains($0.text("role"))}) {u in Text(u.text("name")).tag(u.id)}};Toggle("I checked this job is active in printIQ",isOn:$confirmed)};Section("Approved stock for this section") {TextField("Search stock",text:$query);ForEach(api.stock.filter {!query.isEmpty && ($0.id+" "+$0.text("name")).localizedCaseInsensitiveContains(query)}.prefix(30)) {s in Toggle(s.id,isOn:Binding(get:{selected.contains(s.id)},set:{if $0 {selected.insert(s.id)}else{selected.remove(s.id)}}))};Text(selected.sorted().joined(separator:", ")).font(.caption)};Button(saved ? "Job added":"Add pilot job") {api.run {guard !api.jobs.contains(where:{$0.id==number}) else {throw AppError("This job already exists. Use its current sections; ask the manager to update an import if needed.")};_ = try await api.action("job",["id":number,"name":name,"rep":rep,"active":true,"sections":[["id":sectionID,"name":sectionName,"stocks":selected.sorted()]]],key:key);saved=true}}.disabled(!confirmed||selected.isEmpty||saved||api.working)}.navigationTitle("Add verified job")}
}
struct VerifyJobForm:View {
    @EnvironmentObject var api:API;let job:Row
    @State private var active=true;@State private var confirmed=false;@State private var key=UUID().uuidString;@State private var saved=false
    var body:some View {Form {Text(job.id);Text(job.text("name"));Toggle("Job is still active",isOn:$active);Toggle("I checked the current printIQ record",isOn:$confirmed);Button(saved ? "Status recorded":"Record verified status") {api.run {_ = try await api.action("job",["id":job.id,"name":job.text("name"),"rep":job.text("rep"),"sections":job.values["sections"] ?? [],"active":active],key:key);saved=true}}.disabled(!confirmed||saved||api.working);Text("This changes the app's verification only. It does not change printIQ status.").font(.footnote)}.navigationTitle("Verify active job")}
}
